import assert from "node:assert/strict";
import {createElement} from "react";
import {renderToStaticMarkup} from "react-dom/server";
import type {Block} from "../../src/core/types";
import type {GeneratedBody} from "../../src/core/generators/definition";
import {Legacy2018TechnicalCircuitFigure} from "../../src/ui/Legacy2018TechnicalCircuitFigures";
import {legacy2018TechnicalCircuitFacts as facts} from "./legacy-2018-technical-circuit-review";
import {technicalAttr as attr} from "./legacy-2018-technical-trace-oracle";
export function legacy2018TechnicalCircuitSvg(b:Block){assert(b.type==="diagram"&&b.scene.kind==="source_figure");assert(b.alt);return renderToStaticMarkup(createElement(Legacy2018TechnicalCircuitFigure,{profile:b.scene.profile,values:b.scene.values,caption:b.caption??""}));}
const nums=(s:string,keys:string[])=>keys.map(k=>Number(attr(s,k)));
const textPositions=(svg:string)=>[...svg.matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)].map(m=>({text:m[2],x:Number(attr(m[1],"x")),y:Number(attr(m[1],"y"))}));
/** Classify the rendered gate outline, XOR's extra input curve and NAND's
 * output bubble; scene values/data names alone cannot establish a gate. */
export function legacy2018ReadMajorityCircuit(svg:string){
 const groups=[...svg.matchAll(/<g data-gate="([0-4])"([^>]*)>([\s\S]*?)<\/g>/g)];assert.equal(groups.length,5);const names=groups.map((m,i)=>{assert.equal(Number(m[1]),i);assert.equal(attr(m[2],"transform"),`translate(${facts.translations[i].join(" ")})`);const paths=[...m[3].matchAll(/<path\b([^>]*)/g)],circle=m[3].match(/<circle\b([^>]*)/);assert(paths.length===1||paths.length===2);const shape=attr(paths[0][1],"d");let name:string;if(shape===facts.shapes.AND){assert.equal(paths.length,1);if(circle){assert.deepEqual(nums(circle[1],["cx","cy","r"]),[78,30,6]);name="NAND";}else name="AND";}else{assert.equal(shape,facts.shapes.OR);assert(!circle);if(paths.length===2){assert.equal(attr(paths[1][1],"d"),facts.shapes.XOR);name="XOR";}else name="OR";}const pins=[...m[3].matchAll(/<line\b([^>]*data-input-pin="[^"]*"[^>]*)/g)].map(p=>nums(p[1],["x1","y1","x2","y2"]));assert.deepEqual(pins,name==="OR"||name==="XOR"?[[0,15,7,15],[0,45,7,45]]:[]);return name;});
 const wires=new Map([...svg.matchAll(/<path\b([^>]*data-wire="[^"]*"[^>]*)/g)].map(m=>[attr(m[1],"data-wire"),attr(m[1],"d")]));assert.equal(wires.size,11);for(const [key,value]of Object.entries(facts.inputPaths))assert.equal(wires.get(key),value);const end=(index:number)=>facts.translations[index][0]+(names[index]==="NAND"?84:72);assert.equal(wires.get("upper-middle"),`M ${end(0)} 80 L 365 80 L 365 125 L 420 125`);assert.equal(wires.get("middle-middle"),`M ${end(1)} 180 L 390 180 L 390 155 L 420 155`);assert.equal(wires.get("middle-final"),`M ${end(3)} 140 L 550 140 L 550 180 L 600 180`);assert.equal(wires.get("lower-final"),`M ${end(2)} 280 L 550 280 L 550 210 L 600 210`);assert.equal(wires.get("output"),`M ${end(4)} 195 L 720 195`);
 const dots=[...svg.matchAll(/<circle\b([^>]*data-junction="[^"]*"[^>]*)/g)].map(m=>nums(m[1],["cx","cy","r"]));assert.deepEqual(dots,[[95,65,4],[125,95,4],[155,195,4]]);assert.deepEqual(textPositions(svg),facts.circuitLabels.map(({text,x,y})=>({text,x,y})));for(const label of facts.circuitLabels){const wire=wires.get(label.wire)!;assert(wire);const points=[...wire.matchAll(/[ML] ([\d.]+) ([\d.]+)/g)].map(m=>[Number(m[1]),Number(m[2])]);assert.deepEqual(label.text==="Y"?points.at(-1):points[0],label.endpoint);assert.equal(label.y,label.endpoint[1]);}
 const gate=(name:string,x:boolean,y:boolean)=>name==="AND"?x&&y:name==="OR"?x||y:name==="XOR"?x!==y:!(x&&y);const truth=Array.from({length:8},(_,i)=>{const a=Boolean(i&4),b=Boolean(i&2),c=Boolean(i&1),ab=gate(names[0],a,b),bc=gate(names[1],b,c),ac=gate(names[2],a,c);return Number(gate(names[4],gate(names[3],ab,bc),ac));});return{names,truth};
}
export function legacy2018ReadMajorityTable(svg:string){const rect=svg.match(/<rect\b([^>]*)/);assert(rect);assert.deepEqual(nums(rect[1],["x","y","width","height"]),[70,30,360,500]);const headers=textPositions(svg).filter(t=>!/^[01]$/.test(t.text));assert.deepEqual(headers,facts.tableHeaders);for(const header of headers){const region=header.text==="入力"?facts.tableHeaderRegions.input:header.text==="出力"?facts.tableHeaderRegions.output:null;if(region)assert(header.x>region[0]&&header.x<region[2]&&header.y>region[1]&&header.y<region[3]);else assert.equal(header.x,facts.tableHeaderRegions.columnCenters["ABCY".indexOf(header.text)]);}const cells=[...svg.matchAll(/<text\b([^>]*data-truth-cell="[^"]*"[^>]*)>([^<]*)<\/text>/g)];assert.equal(cells.length,32);const rows=Array.from({length:8},()=>[] as number[]);cells.forEach((m,index)=>{const row=Math.floor(index/4),col=index%4;assert.equal(attr(m[1],"data-truth-cell"),`${row}-${col}`);assert.deepEqual(nums(m[1],["x","y"]),[facts.tableHeaderRegions.columnCenters[col],155+row*50]);assert(/^[01]$/.test(m[2]));rows[row].push(Number(m[2]));});for(const [i,row] of rows.entries())assert.deepEqual(row,[i>>2,(i>>1)&1,i&1,Number((i>>2)+((i>>1)&1)+(i&1)>=2)]);const lines=[...svg.matchAll(/<line\b([^>]*)/g)].map(m=>nums(m[1],["x1","y1","x2","y2"]));assert.deepEqual(lines,[...Array.from({length:9},(_,i)=>[70,80+i*50,430,80+i*50]),[160,80,160,530],[250,80,250,530],[340,30,340,530]]);return rows.map(row=>row[3]);}
export function legacy2018TechnicalCircuitOracle(b:GeneratedBody,v:number[]){assert.equal(v.length,3);assert(v.every(n=>n===0||n===1));assert.equal(b.prompt.length,2);assert(b.prompt[0].type==="paragraph");assert.equal(b.prompt[0].text,facts.stem);const target=legacy2018ReadMajorityTable(legacy2018TechnicalCircuitSvg(b.prompt[1]));assert.deepEqual(target,facts.truth);assert.equal(b.choices.length,4);const actual=b.choices.map((bs,i)=>{assert.equal(bs.length,1);const read=legacy2018ReadMajorityCircuit(legacy2018TechnicalCircuitSvg(bs[0]));assert.deepEqual(read.names,i===0?facts.originalGateNames[0]:v[i-1]?facts.changedGateNames[i-1]:facts.originalGateNames[i]);if(i===0||!v[i-1])assert.deepEqual(read.truth,facts.originalTruth[i]);return read.truth;});assert.equal(new Set(actual.map(row=>row.join(""))).size,4,"no equivalent distractor truth functions");const truth=actual.map(row=>row.every((n,i)=>n===target[i]));assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));for(const text of ["二つ以上が1","AB＋BC＋AC","入力000から111までの全8状態","橋形"])assert(b.explanation.includes(text));return actual;}
